function echoZeros(arr: number[]): void {
  const out: number[] = [];
  for (const v of arr) {
    if (out.length === arr.length) break;
    out.push(v);
    if (v === 0 && out.length < arr.length) out.push(0);
  }
  for (let i = 0; i < arr.length; i++) arr[i] = out[i];
}

