function echoZeros(arr: number[]): void {
  const n = arr.length;
  let zeros = 0;
  for (const v of arr) if (v === 0) zeros++;
  let j = n + zeros - 1;
  for (let i = n - 1; i >= 0 && j >= 0; i--) {
    if (j < n) arr[j] = arr[i];
    j--;
    if (arr[i] === 0) {
      if (j < n) arr[j] = 0;
      j--;
    }
  }
}

